/* bench.c - times dynamic_array.h operations as the array grows. Do not edit this file.

   `make bench` builds this twice, once with the naive array and once with yours, and
   runs both. Each table doubles n and does n of one operation. Watch the ns/op column:
   if it stays flat as n doubles, each operation costs the same however big the array
   is. If it doubles too, each operation costs more the bigger the array, and doing n of
   them costs about four times as much every time n doubles. A row that would take too
   long is skipped. */

#define _POSIX_C_SOURCE 199309L

#include <stdio.h>
#include <time.h>

#include "alloc_stats.h"
#include "dynamic_array.h"

#ifndef IMPL_NAME
#define IMPL_NAME "yours"
#endif

#define MIN_N 1024
#define MAX_N 262144
#define BUDGET_SECONDS 2.0

typedef enum { OP_ADD, OP_GET, OP_REMOVE_LAST, OP_INSERT_FRONT } Op;

static const char *op_names[] = {
  "da_add (to the end)",
  "da_get (every index)",
  "da_remove_at (the last index)",
  "da_insert (at index 0)",
};

static double now(void)
{
  struct timespec t;
  clock_gettime(CLOCK_MONOTONIC, &t);
  return (double)t.tv_sec + (double)t.tv_nsec / 1e9;
}

/* A new array holding 0 .. n - 1, built quickly with da_reserve so building it is not
   part of what gets timed. */
static DynamicArray *filled(size_t n)
{
  DynamicArray *a = da_new();
  da_reserve(a, n);
  for (size_t i = 0; i < n; i++) {
    da_add(a, (int)i);
  }
  return a;
}

/* Does n of op and returns the seconds it took. Stores the allocations made in *allocs. */
static double run(Op op, size_t n, size_t *allocs)
{
  DynamicArray *a = op == OP_GET || op == OP_REMOVE_LAST ? filled(n) : da_new();
  volatile long sink = 0;
  alloc_stats_reset();
  double start = now();
  for (size_t i = 0; i < n; i++) {
    int value = 0;
    switch (op) {
    case OP_ADD:
      da_add(a, (int)i);
      break;
    case OP_GET:
      da_get(a, i, &value);
      sink += value;
      break;
    case OP_REMOVE_LAST:
      da_remove_at(a, n - 1 - i, &value);
      sink += value;
      break;
    case OP_INSERT_FRONT:
      da_insert(a, 0, (int)i);
      break;
    }
  }
  double seconds = now() - start;
  AllocStats s;
  alloc_stats_get(&s);
  *allocs = s.allocs;
  da_free(a);
  return seconds;
}

int main(void)
{
  printf("Benchmark: %s dynamic array\n", IMPL_NAME);
  for (Op op = OP_ADD; op <= OP_INSERT_FRONT; op++) {
    printf("\n%s\n", op_names[op]);
    printf("%10s %12s %12s %12s\n", "n", "total ms", "ns/op", "allocs");
    double last = 0.0;
    for (size_t n = MIN_N; n <= MAX_N; n *= 2) {
      if (last * 4.0 > BUDGET_SECONDS) {
        printf("%10zu %12s\n", n, "(too slow: skipped)");
        continue;
      }
      size_t allocs = 0;
      last = run(op, n, &allocs);
      printf("%10zu %12.2f %12.1f %12zu\n", n, last * 1e3, last * 1e9 / (double)n, allocs);
    }
  }
  return 0;
}
